if (!function_exists('tpi_nav_icon')) {
    /**
     * 输出一个底栏图标
     *
     * @param string $key home / products / message / about-us / contact
     * @return string 内联 svg；未知 key 返回空字符串
     */
    function tpi_nav_icon(string $key): string
    {
        static $cache = [];
        $key = strtolower(trim($key));
        if (isset($cache[$key])) {
            return $cache[$key];
        }

        $map  = tpi_nav_icons_file_map();
        $name = $map[$key] ?? '';
        $file = $name !== '' ? THEME_DIR . 'assets/svg/' . $name : '';
        $svg  = ($file !== '' && is_file($file)) ? (string) file_get_contents($file) : '';

        // 文件被弄成空文件、只剩半截时也走内置那份
        if ($svg === '' || strpos($svg, '<svg') === false || strpos($svg, '</svg>') === false) {
            $svg = tpi_nav_icons()[$key] ?? '';
        }

        return $cache[$key] = $svg;
    }
}

if (!function_exists('tpi_nav_icons_file_map')) {
    /** key => 主题里的文件名 */
    function tpi_nav_icons_file_map(): array
    {
        return [
            'home'     => 'Home.svg',
            'products' => 'Products.svg',
            'message'  => 'Message.svg',
            'about-us' => 'About-us.svg',
            'contact'  => 'Contact-us.svg',
        ];
    }
}